end local bv={['Spectate / Stop Spectating']=[[Watch the selected player. Keeps following them after they respawn. Switches to a backup camera by itself if the game blocks the normal one.]],['Always Use Backup Spectate Camera']=
[[Spectate with our own orbit camera (right mouse to look, scroll to zoom). Use it if spectating looks wrong in a game.]],['Teleport to Target']='Teleport next to the selected player.',['Sort Players (Name / Distance)']=
[[Order the player list by name or by how close they are to you.]],['Copy Profile Link']=[[Copy the selected player's Roblox profile URL to your clipboard.]],['Sit On Head']='Sit on top of the selected player and stay there.',[
'Fling Target (Burst)']='Push the selected player with a short burst of velocity.',['Jumpscare Duration']=[[How long Jumpscare keeps you in front of the target before you snap back.]],['Jumpscare Target']=
[[Teleport in front of the target's face, then return to where you were.]],['Chat Spam']=[[Send the message in the box every 0.5 s. Chat filters and rate limits apply.]],['Auto Follow Target']=
[[Stay 3 studs behind the selected player and match their walk speed.]],['Invisible (Server-side)']=[[Others can't see you; you play as a see-through copy. Turn off to come back.]],['Fly  (WASD + Space/Shift)']=
[[Fly where the camera looks. Space/E up, Shift/Q down. Survives respawns.]],['Fly Speed']='How fast Fly moves you, in studs per second.',['Walk Speed']=[[Your walking speed (16 is normal). Re-applied after you respawn.]],['Jump Power']=
[[How high you jump (50 is normal). Re-applied after you respawn.]],['Noclip']='Walk through walls and objects.',['Ctrl+Click Teleport']=[[Hold Ctrl and left-click anywhere in the world to teleport there.]],['Godmode']=
[[Sets your health to infinite on your side. Many games still kill you server-side.]],['Infinite Jump']='Jump again in mid-air every time you press Space.',['Anti-Fling']=
[[Cancels sudden huge sideways speed so other exploiters can't fling you.]],['Anti-AFK']=[[Stops Roblox from kicking you for being idle for 20 minutes.]],['Change UserId to Creator']=
[[Locally pretend to be the game's creator. Only affects scripts on your side.]],['Give Jerk Tool']='Adds an animation tool to your backpack.',['Keep Emote While Moving']=
[[Keep the emote going when you walk (on by default). Off = Roblox's normal behaviour: moving stops it.]],['Emote Speed']='Play emotes slower or faster.',['Reload Emote List']='Download the emote list again.',['Empty All Emote Folders']=
[[Take every emote out of every folder. The folders themselves stay.]],['Chams (Always-On-Top)']=[[Highlight every player through walls. Roblox only draws about 31 at once.]],['Rainbow Chams']=
'Cycle the chams colours. Needs Chams turned on.',['Name ESP']='Show display names above players, through walls.',['Health Bar ESP']='Show a health bar above every player.',['Show Distance']=
[[Add how far away each player is (in studs) after their name. Needs Name ESP.]],['Team Colors']=[[Colour chams, names and tracers by each player's team colour.]],['Hide Teammates']=
[[Skip players on your team for all ESP and tracers. Does nothing in games without teams.]],['Max ESP Distance']=[[Only show ESP and tracers for players closer than this. 0 = no limit.]],['Tracers']=
[[Draw a line from the bottom of your screen to every player on screen.]],['Infinite Zoom']='Let the camera zoom out up to 3000 studs.',['Camera Distance']='Lock the camera at this distance from your character.',['Freecam']=
[[Fly the camera freely: WASD, E/Space up, Q/Shift down, hold right mouse to look, Ctrl = faster.]],['Freecam Speed']=[[How fast Freecam flies, in studs per second (hold Ctrl for 3x).]],['Watermark']=
[[Small draggable box with FPS, ping and the voice-ban countdown.]],['Keybind List']=[[Small draggable list of toggles that are on and have a keybind.]],['Fullbright']=
[[Max brightness, no fog, no shadows or colour effects. Turn off to restore.]],['Brightness']='Overall lighting brightness.',['Time of Day']='Change the in-game clock (on your screen only).',['Fog Distance']=
'How far away fog starts hiding things.',['Remove All Fog']='Push the fog out of view.',['Clear Weather Effects']='Turn off atmosphere, blur, sun rays and depth of field.',['Hide Purchase Prompts']=
[[Close the game's 'buy this' pop-ups as soon as they open (like pressing X). Nothing is bought.]],['Remove Invisible Walls']=
[[Walk through invisible barriers, including ones that load later. Floors and characters stay solid. Turn off to restore.]],['Performance Mode']=
[[More FPS: turns off shadows, particles, trails, decals and textures. Turn off to put them back.]],['FPS Cap']=[[Limit your frame rate (needs setfpscap in your executor). 0 = no limit.]],['Save Current Position']=
